"""Small sales report helpers used by the team."""

import csv


def load_sales(path):
    rows = []
    with open(path) as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            rows.append((row["item"], float(row["amount"])))
    return rows


def total(rows):
    result = 0.0
    for _, amount in rows:
        result += amount
    return result


def average(rows):
    if not rows:
        return 0.0
    return total(rows) / len(rows)


def format_currency(value):
    return "%.2f" % value


def top_item(rows):
    best = None
    for item, amount in rows:
        if best is None or amount > best[1]:
            best = (item, amount)
    return best


def summarize(rows):
    lines = []
    lines.append("items: %d" % len(rows))
    lines.append("total: %s" % format_currency(total(rows)))
    lines.append("average: %s" % average(rows))
    return lines


def main():
    rows = load_sales("sales.csv")
    for line in summarize(rows):
        print(line)


if __name__ == "__main__":
    main()

