def tokenize(expr):
    return [c for c in expr if not c.isspace()]

def compile_expr(expr):
    tokens = tokenize(expr)
    out = []
    for token in tokens:
        if token.isdigit():
            out.append(('push', int(token)))
        elif token == '+':
            out.append(('add',))
        else:
            raise ValueError('unsupported token: ' + token)
    return out

