def draw_frame(name):
    devices = json.load(open("devices.json"))
    overrides = json.load(open("frame_overrides.json"))
    frame = dict(devices[name])
    if name in overrides:
        frame.update(overrides[name])
    if "Duo" in name:
        frame["has_notch"] = True
        frame["top_inset"] = 0
    lines = []
    if frame["has_notch"]:
        lines.append(" ____ ")
    status = "status"
    pad = frame["top_inset"]
    width = frame["width"]
    if pad + len(status) > width:
        pad = max(0, width - len(status))
    lines.append("|" + " " * pad + status + " " * (width - pad - len(status)) + "|")
    return "\n".join(lines)

